{
  "models": [
    {
      "name": "ads_csmr_brand_category_input_df",
      "description": "门店同品类品牌输入关联分析。粒度：统计周期×门店×品牌。维度：统计周期、统计时间、门店、品牌。度量：关联消费品类Top5(category_name_top_1~5)、同品类关联输入品牌Top5(id/名称/输入关联度)、全商场关联输入品牌Top5(id/名称/输入关联度)。注意：TopN 宽表，品牌名在列值而非维度列。「输入」= 消费该品牌的客人还买了哪些品牌。",
      "column_count": 44
    },
    {
      "name": "ads_csmr_brand_category_output_df",
      "description": "门店同品类品牌输出关联分析。粒度：统计周期×门店×品牌。维度：统计周期、统计时间、门店、品牌。度量：同品类关联输出品牌Top5、全商场关联输出品牌Top5（均含 id/名称/输出关联度）。注意：TopN 宽表；「输出」= 该品牌的客人流失后流向哪些品牌。",
      "column_count": 39
    },
    {
      "name": "ads_csmr_store_brand_attr_analysis_df",
      "description": "客群门店品牌属性分析（文档表名 ads_csmr_store_brand_attribute_analysis_df，库中为 attr 缩写）。粒度：统计周期×门店×品牌。维度：统计周期、门店、品牌。度量：6 档年龄占比(<25/26-35/36-45/46-55/56-65/≥66)及同比、男性占比及同比、女性占比及同比。",
      "column_count": 29
    },
    {
      "name": "ads_csmr_store_brand_drain_df",
      "description": "门店品牌消费客群品牌流失分析。粒度：统计周期×门店×品牌。维度：周期时间、门店、品牌。度量：品牌流失率(前年/去年/本期)、门店品牌TOP20%会员在品牌年度流失人数占比、1~12个月及一年以上分层流失人数、近一年门店平均休眠周期及同比。注意：与 ads_csmr_store_drain_df 的区别是「流向其他品牌」而非流向商场外。",
      "column_count": 26
    },
    {
      "name": "ads_csmr_store_brand_drain_drc_df",
      "description": "品牌流失会员去向。粒度：统计周期×门店×品牌。维度：周期时间、门店、品牌。度量：流失会员去向品牌Top10(名称+人数，store_brand_drain_drc_1~10)。注意：TopN 宽表；「流失会员去了哪些品牌」用本表。",
      "column_count": 27
    },
    {
      "name": "ads_csmr_store_brand_frq_analysis_df",
      "description": "客群门店品牌频次分析。粒度：统计周期×门店×品牌。维度：统计周期、门店、品牌。度量：品牌复购率(本期/去年/前年)、品牌侧与门店侧 1~8 天及以上到店天数分段人数、各段同比、各段占比。注意：分段含义为「周期内到店天数」，8 表示 8 天及以上。",
      "column_count": 60
    },
    {
      "name": "ads_csmr_store_brand_new_mbr_sale_df",
      "description": "品牌新客销售表。粒度：统计周期×门店×品类×品牌。维度：统计周期、时间、门店、品类(中类)、品牌。度量：品牌新客人数(前年/去年/本期)、与品类新客中位数差异、品类新客人数及同比、新客金额/客单价/笔数及同比、人均消费笔数及同比。注意：与 trd 域的同名表重复，问品牌新客优先用本表（trd 版未上线）。",
      "column_count": 24
    },
    {
      "name": "ads_csmr_store_brand_trd_analysis_df",
      "description": "客群门店品牌销售分析·消费金额分层。粒度：统计周期×门店×品牌。维度：统计周期、门店、品牌。度量：品牌侧与门店侧各7档消费金额段人数(<3千/3-5千/5千-1万/1-2万/2-3万/3-5万/≥5万)、各档同比人数、各档人数占比。注意：分段值写在列名里(brand_amt_range_person_cnt_1~7)，回答「哪个金额段人最多」需比较同组多列。",
      "column_count": 51
    },
    {
      "name": "ads_csmr_store_brand_whole_sale_df",
      "description": "客群门店品牌销售人数分析。粒度：统计周期×门店×品类×品牌。维度：门店、品类(中类)、品牌、供应商、品牌在门店的合作模式。度量：会员消费人数(前年同期/去年同期/本期)、人数与中位数差异、品牌在品类的销售/营收排名、品牌销售/营收排名、销售毛利率、回款率、销售坪效、营收坪效、消费品牌数、门店品牌TOP20%会员占比、门店销售、门店会员销售额、门店会员贡献率、门店会员客单价、门店活跃度（以上均含同比 _yoy 列）。注意：同比一律用 _yoy 预计算列，勿自行重算。",
      "column_count": 43
    },
    {
      "name": "ads_csmr_store_drain_df",
      "description": "门店品牌消费客群商城流失分析。粒度：统计周期×门店×品牌。维度：周期时间、门店、品牌。度量：1~12个月及一年以上分层流失人数(离开本商场)、门店平均休眠周期及同比。注意：与 brand_drain 表的区别是「流向商场外」。",
      "column_count": 22
    },
    {
      "name": "ads_mall_csmr_csmr_brand_tag_df",
      "description": "消费者×品牌标签表（文档未描述，由 schema 归纳）。粒度：会员(oneid)×品牌。门店/品牌粒度的会员标签明细，供品牌维度客群分析下钻使用。实测约 6,820 万行。",
      "column_count": 12
    },
    {
      "name": "ads_mall_csmr_csmr_category_tag_df",
      "description": "消费者×品类标签表（文档未描述，由 schema 归纳）。粒度：会员(oneid)×品类。品类粒度的会员标签明细。实测约 3,435 万行。",
      "column_count": 13
    },
    {
      "name": "ads_mall_csmr_csmr_tag_df",
      "description": "消费者标签表·全域（文档表名 ads_csmr_csmr_tag_df）。粒度：会员(oneid)。无门店维度。属性：会员/客户 id、手机号、是否粉丝/企微用户/会员/至臻金卡/潜客、性别、年龄、留资/注册日期、会员状态、来源渠道、注册门店、等级、省市县区、所属导购。用于「全市/全部会员」类画像。⚠️ 含手机号等敏感字段，默认不输出。",
      "column_count": 21
    },
    {
      "name": "ads_mall_csmr_store_csmr_3y_tag_df",
      "description": "门店消费者三年标签表（文档未描述，由 schema 归纳）。粒度：会员(oneid)×门店，覆盖近三年窗口。用于跨年度的会员标签对比。实测约 374 万行。",
      "column_count": 14
    },
    {
      "name": "ads_mall_csmr_store_csmr_tag_df",
      "description": "门店消费者标签表（文档表名 ads_csmr_store_csmr_tag_df）。粒度：会员(oneid)×门店。属性：会员/客户 id、手机号、是否粉丝/企微用户/会员/至臻金卡/潜客、性别、年龄、留资/注册日期、会员状态、来源渠道、注册门店、等级、省市县区、所属导购。消费标签：近365天消费品牌数/品类数/日均消费金额/平均购买间隔/金额分段/累计次数/贡献金额/实际贡献价值/品牌偏好Top3、年度平均到店周期、券/停车/权益/积分/礼品投入、积分返利券到期预警、新人礼包领取后使用情况。⚠️ 含手机号等敏感字段，默认不输出。",
      "column_count": 52
    },
    {
      "name": "ads_mall_csmr_wechat_guide_df",
